/*
# Corregir separador de texto en Victoria's Secret (guion largo -> punto medio)

1. Data Changes
- Los 5 productos Victoria's Secret usaban '-' en subtitle/notes en vez de '.',
  inconsistente con el resto del catalogo. Corregido.
*/

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  subtitle = EXCLUDED.subtitle,
  family = EXCLUDED.family,
  notes = EXCLUDED.notes,
  price = EXCLUDED.price,
  volume = EXCLUDED.volume,
  accent = EXCLUDED.accent,
  image = EXCLUDED.image,
  description = EXCLUDED.description,
  updated_at = now();
